 const teacherCredential=()=>undefined;
 let sharedYear=Number($('life-year').value),yearPending=false;function scope(){if(!canEnter()||!lifeCloud?.user)throw Error('NORMAL 통합 인증이 필요합니다.');const visible=Number($('life-year').value);if(yearPending||visible!==sharedYear||!Number.isInteger(visible)||visible<2000||visible>2100)throw Error('표시 학년도와 저장 학년도가 일치하지 않습니다. 전환을 완료하세요.');const result={year:sharedYear,classId:window.__TT_STAGE031_CLASS.activeId};Object.defineProperty(result,'generation',{value:scopeGeneration});return result}
 let questionDefinitions;
 async function surveyQuestions(){
  if(!questionDefinitions)questionDefinitions=Promise.all([import('../survey/core.mjs'),fetch('../classroom/survey/v0.2.md')]).then(async ([module,response])=>{if(!response.ok)throw Error('설문 문항을 불러오지 못했습니다.');return module.parseQuestions(await response.text())}).catch(error=>{questionDefinitions=null;throw error});
  return questionDefinitions;
 }
 function displayDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'시각 확인 불가':new Intl.DateTimeFormat('ko-KR',{dateStyle:'long',timeStyle:'short'}).format(date)}
 function responseLines(body,month,students,definitions){
  const names=new Map(students.map(student=>[String(student.id),student.name]));
  const peers=choices=>choices.map(choice=>`${names.get(String(choice.studentId))||'명단에서 확인할 수 없는 학생'}${choice.behavior?' · '+choice.behavior:''}`).join('\n');
  return (definitions[month]||[]).map(question=>{
   const answer=body?.[question.number];let text;
   if(answer===null||answer===undefined||answer==='')text='미응답';
   else if(Array.isArray(answer))text=answer.length?peers(answer):'선택한 친구 없음';
   else if(typeof answer==='object')text=answer.kind==='unknown'?'잘 모르겠어요':answer.kind==='declined'?'선택하고 싶지 않아요':answer.kind==='selected'&&Array.isArray(answer.choices)?peers(answer.choices)||'선택한 친구 없음':'응답을 표시할 수 없습니다.';
   else text=String(answer);
   return {question:`${question.number}. ${question.text}`,answer:text};
  });
 }
 function renderResponse(container,student,row,month,students,definitions){
  container.replaceChildren();const heading=document.createElement('h3');heading.textContent=`${student.name} · ${month}월 설문`;container.append(heading);
  const info=document.createElement('p');info.textContent=row?`제출 ${displayDate(row.submitted_at)}`:'아직 제출하지 않았습니다.';container.append(info);if(!row)return;
  for(const line of responseLines(row.body,month,students,definitions)){const item=document.createElement('div'),question=document.createElement('strong'),answer=document.createElement('p');item.className='life-answer';question.textContent=line.question;answer.textContent=line.answer;item.append(question,answer);container.append(item)}
 }
 $('life-charm-preview').addEventListener('click',async()=>{try{const currentScope=scope(),params=`year=${currentScope.year}&classId=${encodeURIComponent(currentScope.classId)}`;const [result,{recommendCharm}]=await Promise.all([api(`/api/v2/teacher/analysis?${params}`,{credential:teacherCredential()}),import('../survey/charm-recommendation.mjs')]);if(scope().classId!==currentScope.classId||scope().year!==currentScope.year)throw Error('학급 또는 학년도가 변경되었습니다.');const snapshot=window.__TT_PE_TRAITS.snapshot(),ids=new Set((classState.students||[]).map(s=>String(s.id)));if(result.roster.length!==ids.size||result.roster.some(s=>!ids.has(s.id)))throw Error('현재 학급 명단과 일치하지 않습니다.');const recommendation=recommendCharm(result.roster,result.responses,snapshot.scale),output=$('life-charm-output');output.replaceChildren();const summary=document.createElement('p');summary.textContent=`${snapshot.scale}단계 · 최소 유효 응답 ${recommendation.minimum}명 · 협력 ${recommendation.counts.cooperation} / 배려 ${recommendation.counts.care} / 인기도 ${recommendation.counts.popularity}명 · 최신 유효 응답 기준`;output.append(summary);for(const row of recommendation.rows){const student=result.roster.find(s=>s.id===row.studentId),current=snapshot.values[row.studentId]?.charm??null,line=document.createElement('p'),button=document.createElement('button');line.textContent=`${student.name} · 현재 ${current??'미설정'} · 추천 ${row.status==='READY'?row.level:row.status==='NO_EVIDENCE'?'보류 (긍정적 선택 없음)':'자료 부족'} · ${row.status==='READY'?(current===row.level?'변경 없음':'미적용'):'보류'}`;if(row.status==='READY'){const details=document.createElement('small');details.textContent=` 협력 ${(row.ratios.cooperation*100).toFixed(1)}% (${row.eligibleCounts.cooperation}명) · 배려 ${(row.ratios.care*100).toFixed(1)}% (${row.eligibleCounts.care}명) · 인기도 ${(row.ratios.popularity*100).toFixed(1)}% (${row.eligibleCounts.popularity}명) · 가중 ${(row.score*100).toFixed(1)}%`;line.append(details);if(current!==row.level){button.type='button';button.textContent='추천값 반영';button.disabled=snapshot.modes.charm!=='manual';button.addEventListener('click',async()=>{if(button.dataset.confirmed!=='yes'){button.dataset.confirmed='yes';button.textContent=`${current??'미설정'} → ${row.level} 확인 후 적용`;status('변경 전후 값을 확인한 뒤 다시 누르면 적용됩니다.');return;}try{if(scope().year!==currentScope.year)throw Error('학년도가 변경되었습니다.');await window.__TT_PE_TRAITS.applyApprovedCharm({classId:currentScope.classId,scale:snapshot.scale,changes:[{id:row.studentId,expected:current,value:row.level}]});button.disabled=true;line.append(document.createTextNode(' · 적용 완료'));status('기존 능력치 저장소에 반영했습니다.')}catch(error){status(`반영 실패: ${error.message}`)}});line.append(button)}}output.append(line)}if(snapshot.modes.charm!=='manual')status('매력 축이 성적 연동 중입니다. 수동 모드로 변경한 후 다시 계산하세요.');else status('추천값을 계산했습니다. 승인 전에는 기존 값이 변경되지 않습니다.')}catch(error){status(`추천 계산 실패: ${error.message}`)}});
