 $('life-timeline-load').addEventListener('click',async()=>{try{const s=scope(),id=$('life-record-student').value,params=`year=${s.year}&classId=${encodeURIComponent(s.classId)}`,credential=teacherCredential();const [analysis,observations,definitions]=await Promise.all([api(`/api/v2/teacher/analysis?${params}`,{credential}),api(`/api/v2/teacher/observations?${params}&studentId=${encodeURIComponent(id)}`,{credential}),surveyQuestions()]);if(!sameScope(s)||$('life-record-student').value!==id)throw Error('조회 중 학급 또는 학생이 변경되었습니다.');if(!analysis.roster.some(x=>x.id===id))throw Error('현재 학급 학생이 아닙니다.');const entries=[];for(const r of analysis.responses.filter(x=>x.student_id===id))entries.push({date:r.submitted_at,text:`학생 자기 보고 · ${r.month}월\n${responseLines(r.body,r.month,analysis.roster,definitions).map(line=>`${line.question}\n${line.answer}`).join('\n\n')}`});for(const month of analysis.monthly)for(const [key,label] of [['cooperation','협력'],['care','배려']])for(const vote of month.categories[key].votes.filter(v=>v.to===id))entries.push({date:analysis.responses.find(r=>r.month===month.month&&r.student_id===vote.from)?.submitted_at||'',text:`친구 칭찬 · ${label} · ${vote.behavior||''}`});for(const item of observations.records)entries.push({date:item.date,text:`교사 관찰 · ${item.category}\n관찰: ${item.fact}\n후속: ${item.followup}`});entries.sort((a,b)=>b.date.localeCompare(a.date));const output=$('life-timeline');output.replaceChildren();for(const entry of entries){const p=document.createElement('p');p.style.whiteSpace='pre-wrap';p.textContent=`${entry.date.includes('T')?displayDate(entry.date):entry.date}\n${entry.text}`;output.append(p)}status(`타임라인 ${entries.length}건`)}catch(error){status(`타임라인 조회 실패: ${error.message}`)}});
