 async function restoreCodes(current,valid){
  const serial=++codesReadSerial;codesState='checking';
  try{const result=await api('/api/v2/teacher/codes?year='+current.year+'&classId='+encodeURIComponent(current.classId));if(!valid()||serial!==codesReadSerial)return;
   if(!Array.isArray(result.codes)||!Array.isArray(result.missing))throw Error('코드 목록 형식 오류');
   const ids=new Set(cloudStudents().map(x=>x.id)),seen=new Set(),next=new Map();
   for(const item of result.codes){const id=String(item.id);if(!ids.has(id)||seen.has(id)||!/^\d{6}$/.test(item.code)||(codeVersions.has(id)&&Number(item.version)!==codeVersions.get(id)))throw Error('코드 목록과 최신 명단 불일치');seen.add(id);next.set(id,item.code)}
   for(const value of result.missing){const id=String(value);if(!ids.has(id)||seen.has(id))throw Error('코드 목록과 최신 명단 불일치');seen.add(id)}if(seen.size!==ids.size)throw Error('코드 목록 누락');
   issuedCodes=next;codesState='ready';
  }catch(error){if(valid()&&serial===codesReadSerial){codesState=error.status===404?'legacy':'error';if(codesState==='error'){issuedCodes.clear();closeCodePrint();resetCodeConfirmations()}}}
 }
